    // 로타리 가운데 섬: [x, z, 반지름]
    for (const [x, z, r] of d.islands || []) t.islands.push({ x: x * S + ox, z: z * S + oz, r: r * S });
    // 지름길: { from, to, ctrl: [[x,z,높이,폭]...], w, jumps: [[0~1, 높이]], boost: 0~1, tunnel }
